mapper.select:
SELECT r.id, r.order_id, o.order_number AS orderNumber, r.customer_id, c.name AS customerName, r.ratee_id, r.rating_type, r.rating_value, r.comment, r.rating_time, CASE r.rating_type WHEN 'DRIVER' THEN d.name WHEN 'MOVER' THEN m.name WHEN 'SERVICE' THEN s.service_name ELSE '未知被评分者' END AS rateeName
FROM rating r JOIN moving_order o ON r.order_id = o.id JOIN customer c ON r.customer_id = c.id LEFT JOIN driver d ON r.rating_type = 'Driver' AND r.ratee_id = d.id LEFT JOIN mover m ON r.rating_type = 'Mover' AND r.ratee_id = m.id LEFT JOIN service s ON r.rating_type = 'Service' AND r.ratee_id = s.id
and r.rating_value >= #{ratingValueMin}
and r.rating_value <= #{ratingValueMax}
and o.order_number like concat('%', #{orderNumber}, '%')
and r.rating_type = #{ratingType}
AND ( (r.rating_type = 'Driver' AND d.name like concat('%', #{rateeName}, '%')) OR (r.rating_type = 'Mover' AND m.name like concat('%', #{rateeName}, '%')) OR (r.rating_type = 'Service' AND s.service_name like concat('%', #{rateeName}, '%')) )
ORDER BY r.id

SELECT r.id AS ratingId, r.ratee_id, r.rating_type, r.rating_value, r.comment, r.rating_time,
CASE r.rating_type WHEN #{ratingTypeDriver} THEN d.name WHEN #{ratingTypeMover} THEN m.name WHEN #{ratingTypeService} THEN s.service_name ELSE '未知对象' END AS rateeName,
CASE r.rating_type WHEN #{ratingTypeDriver} THEN '对司机' WHEN #{ratingTypeMover} THEN '对搬运工' WHEN #{ratingTypeService} THEN '对服务' ELSE '未知类型' END AS ratingTypeLabel FROM rating r LEFT JOIN driver d ON r.rating_type = #{ratingTypeDriver} AND r.ratee_id = d.id LEFT JOIN mover m ON r.rating_type = #{ratingTypeMover} AND r.ratee_id = m.id LEFT JOIN service s ON r.rating_type = #{ratingTypeService} AND r.ratee_id = s.id WHERE r.order_id = #{orderId}

SELECT r.id AS rating_id, r.order_id,
mo.order_number, c.name AS customer_name,
r.rating_value, SUBSTRING(r.comment, 1, 200) AS comment_snippet,
r.rating_time AS rating_time
FROM rating r LEFT JOIN moving_order mo ON r.order_id = mo.id LEFT JOIN customer c ON r.customer_id = c.id WHERE r.ratee_id = #{moverId} AND r.rating_type = 'MOVER'
AND r.rating_value >= #{queryDTO.minRatingValue}
AND r.rating_value <= #{queryDTO.maxRatingValue}
AND r.create_time >= #{queryDTO.startTime}
AND r.create_time <= #{queryDTO.endTime}
AND mo.order_number LIKE CONCAT('%', #{queryDTO.orderNumber}, '%')
AND c.name LIKE CONCAT('%', #{queryDTO.customerName}, '%')
ORDER BY r.create_time DESC
